-- ============================================================
-- SchedPro MES seed data for Azure HorizonDB (PostgreSQL 17)
-- Run against the "schedpro" database AFTER creating the schema:
--   psql "host=$PGHOST_RW dbname=schedpro user=$PGUSER sslmode=require" -f seed.sql
-- Safe to re-run: it clears the three tables and reloads them.
-- IDs are generated by the database (no hard-coded IDs).
-- ============================================================

\echo '>> Clearing existing data'
TRUNCATE production_events, work_orders, machines RESTART IDENTITY;

-- ------------------------------------------------------------
-- 1. Machines: 6 machines across 2 German plants
-- ------------------------------------------------------------
\echo '>> Loading machines'
INSERT INTO machines (plant_code, machine_code, machine_type, status, target_oee) VALUES
    ('PLT-DE01', 'CNC-101',   'CNC',     'ACTIVE', 85.0),
    ('PLT-DE01', 'CNC-102',   'CNC',     'ACTIVE', 85.0),
    ('PLT-DE01', 'PRESS-201', 'PRESS',   'ACTIVE', 82.0),
    ('PLT-DE02', 'CNC-301',   'CNC',     'ACTIVE', 85.0),
    ('PLT-DE02', 'ROBOT-401', 'ROBOT',   'ACTIVE', 88.0),
    ('PLT-DE02', 'WELD-501',  'WELDING', 'ACTIVE', 87.0);

-- ------------------------------------------------------------
-- 2. Work orders: machine_id is looked up by machine_code
-- ------------------------------------------------------------
\echo '>> Loading work orders'
INSERT INTO work_orders
    (machine_id, work_order_number, part_number, customer_code,
     planned_qty, actual_qty, status, shift)
SELECT m.machine_id, v.work_order_number, v.part_number, v.customer_code,
       v.planned_qty, v.actual_qty, v.status, v.shift
FROM (VALUES
    ('CNC-101',   'WO-2026-1001', 'BRK-4401',  'OEM-001',  500, 425, 'IN_PROGRESS', 'A'),
    ('CNC-102',   'WO-2026-1002', 'SHAFT-220', 'OEM-002',  800, 720, 'IN_PROGRESS', 'A'),
    ('PRESS-201', 'WO-2026-1003', 'PANEL-310', 'OEM-003', 1000, 910, 'IN_PROGRESS', 'B'),
    ('CNC-301',   'WO-2026-1004', 'GEAR-115',  'OEM-001',  600, 600, 'COMPLETED',   'A'),
    ('ROBOT-401', 'WO-2026-1005', 'FRAME-520', 'OEM-004',  400, 348, 'IN_PROGRESS', 'B'),
    ('WELD-501',  'WO-2026-1006', 'WELD-710',  'OEM-002',  750, 690, 'IN_PROGRESS', 'C'),
    ('CNC-101',   'WO-2026-1007', 'BRK-4402',  'OEM-003',  450, 180, 'IN_PROGRESS', 'B'),
    ('CNC-301',   'WO-2026-1008', 'GEAR-116',  'OEM-005',  500, 125, 'QUEUED',      'C')
) AS v(machine_code, work_order_number, part_number, customer_code,
       planned_qty, actual_qty, status, shift)
JOIN machines m ON m.machine_code = v.machine_code;

-- ------------------------------------------------------------
-- 3. Production events: 200,000 PLC readings over the last 24 hours
--    Deterministic (no random()), so every learner gets the same shape:
--      ~45% temperature, 25% speed, 25% cycle time,
--       3% downtime, 1% quality alert, 1% pressure (press machines only)
-- ------------------------------------------------------------
\echo '>> Loading 200,000 production events (a few seconds)'
INSERT INTO production_events (machine_id, event_type, event_value, plc_id, recorded_at)
WITH numbered AS (
    SELECT machine_id, machine_code, machine_type,
           row_number() OVER (ORDER BY machine_id) AS n
    FROM machines
),
raw AS (
    SELECT g,
           1 + (g % 6) AS n,          -- which machine
           g / 6       AS k,          -- independent counter used for values
           (g / 6) % 100 AS r         -- decides the event type
    FROM generate_series(1, 200000) AS g
),
typed AS (
    SELECT raw.g, raw.k, m.machine_id, m.machine_code,
           CASE
               WHEN raw.r < 40 THEN 'TEMPERATURE'
               WHEN raw.r < 65 THEN 'SPEED'
               WHEN raw.r < 90 THEN 'CYCLE_TIME'
               WHEN raw.r < 96 THEN CASE WHEN m.machine_type = 'PRESS'
                                         THEN 'PRESSURE' ELSE 'TEMPERATURE' END
               WHEN raw.r < 99 THEN 'DOWNTIME'
               ELSE 'QUALITY_ALERT'
           END AS event_type
    FROM raw
    JOIN numbered m ON m.n = raw.n
)
SELECT machine_id,
       event_type,
       CASE event_type
           WHEN 'TEMPERATURE'   THEN 60  + (k % 250) / 10.0   -- 60.0 - 85.0 C
           WHEN 'SPEED'         THEN 900 + (k % 80) * 10      -- 900 - 1690 rpm
           WHEN 'CYCLE_TIME'    THEN 8   + (k % 110) / 10.0   -- 8.0 - 18.9 s
           WHEN 'PRESSURE'      THEN 170 + (k % 250) / 10.0   -- 170.0 - 195.0 bar
           WHEN 'DOWNTIME'      THEN 1   + (k % 10)           -- 1 - 10 minutes
           ELSE 1                                              -- quality alert flag
       END,
       'PLC-' || machine_code,
       now() - g * interval '432 milliseconds'               -- spreads rows over 24 h
FROM typed;

ANALYZE;

-- ------------------------------------------------------------
-- 4. Verify the load
-- ------------------------------------------------------------
\echo '>> Row counts (expect 6, 8, 200000)'
SELECT (SELECT count(*) FROM machines)          AS machines,
       (SELECT count(*) FROM work_orders)       AS work_orders,
       (SELECT count(*) FROM production_events) AS production_events;

\echo '>> Events by type'
SELECT event_type, count(*) AS events
FROM production_events
GROUP BY event_type
ORDER BY events DESC;
